@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1945  cases=61
@exercises tuning (tuning), commandManager (h.cmgr), configManager (h.cm), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cmgr:scope, cmgr:installManifest, cmgr:auditManifests, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-185
  @fn seedItems(h, takes, srcLen)  @ 201-206
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 208-217
  @fn trackList(trackCount)  @ 219-225
  @fn mapBox(tv, take)  @ 228-232
      -- The box the map draws for a take: the travel consumes the window's own shapes.
  @fn mapTracker(harness, inst, trackCount)  @ 237-251
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, the harness behind it for the cmgr, and the page itself.
  @fn chaseTracker(harness)  @ 255-280
      -- A tracker on track 0, bound to 'a0' in its first slot: 'b8' fills the second slot
      -- at QN 8, an audio item lies at 16, and 'c4' sits on the track beside it at 4.

# Cases
  @case 'the manifest declares every command the tracker page registers'  [harness]  @ 287-307
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 311-319
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 322-331
  @case 'focusState before any render returns both bits false'  [harness]  @ 334-341
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 347-360
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 364-381
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 387-408
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 414-432
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 439-457
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 463-496
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 500-524
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 530-560
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 564-585
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 589-602
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 608-642
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 646-660
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 664-687
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 691-727
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 731-766
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 773-790
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 794-817
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 821-844
  @case 'with follow on, the play head carries the tracker across the bound track's slots'  [harness]  @ 850-865
  @case 'with follow off, the head entering another slot leaves the tracker where it was'  [harness]  @ 869-876
  @case 'the chase brackets no loop and raises no map tab'  [harness]  @ 880-895
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 899-934
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 938-986
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 990-1027
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 1031-1065
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 1069-1085
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 1094-1112
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 1116-1132
  @case 'while following, the map window pages off the play head'  [harness]  @ 1136-1146
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 1150-1157
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1161-1172
  @case 'the map window carries the transport it meets, and only that'  [harness]  @ 1176-1199
  @case 'the map loop candidate snaps to the cell, widens to one, and holds at 0'  [harness]  @ 1203-1222
  @case 'the map drives the transport, and a hand-set loop drops loop to item'  [harness]  @ 1226-1237
  @case 'a click on a map box travels to its instance, across tracks as well as slots'  [harness]  @ 1241-1280
  @case 'a map box that is no stop refuses the travel, as the walk passes it over'  [harness]  @ 1284-1298
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1302-1311
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1315-1356
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1360-1387
  @case 'while following, the grid pages the scroll to hold the play row'  [harness]  @ 1391-1437
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1441-1465
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1472-1493
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1499-1523
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1530-1549
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1553-1572
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1576-1598
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1604-1622
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1626-1644
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1648-1670
  @case 'Esc clears the loop and drops loop to item with it'  [harness]  @ 1674-1685
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1689-1713
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1719-1774
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1782-1811
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1817-1860
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1866-1880
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1887-1919
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1923-1943

